#!/usr/bin/env python3
"""Regenerate synthetic test words with glslangValidator; no game shaders or assets."""
from pathlib import Path
import struct
import subprocess
import tempfile

HERE = Path(__file__).resolve().parent
SOURCES = {
    'PatchVert': ('vert', '''#version 450
layout(location=0) in vec2 position;
void main() { gl_Position=vec4(position,0,1); }
'''),
    'PatchFrag': ('frag', '''#version 450
layout(location=0) in vec4 color;
layout(location=0) out vec4 result;
layout(location=1) out vec4 info;
void main() { result=color; info=vec4(0); }
'''),
}
for binding in (0, 1):
    SOURCES[f'BindingFrag{binding}'] = ('frag', f'''#version 450
layout(set=0,binding={binding},std430) readonly buffer Payload {{ vec4 value; }} payload;
layout(location=0) out vec4 color;
layout(location=1) out vec4 info;
void main() {{ color=payload.value; info=vec4(0); }}
''')
for count in (14, 16):
    declarations = '\n'.join(f'layout(location={i}) patch out vec4 p{i};' for i in range(count))
    stores = '\n'.join(f'p{i}=vec4({(i+1)*.01:.2f}+float(gl_PrimitiveID)*0.2)+vec4(0,0.1,0.2,0.3);' for i in range(count))
    SOURCES[f'PatchControl{count}'] = ('tesc', '''#version 450
layout(vertices=3) out;
''' + declarations + '''
void main() {
 gl_out[gl_InvocationID].gl_Position=gl_in[gl_InvocationID].gl_Position;
 if(gl_InvocationID==0) {
''' + stores + '''
  gl_TessLevelOuter[0]=4;gl_TessLevelOuter[1]=4;gl_TessLevelOuter[2]=4;
  gl_TessLevelInner[0]=4;
 }
}
''')
for name, indices in [('Leading', range(4,14)), ('Middle', [0,2,5,9,13]), ('Trailing', range(6))]:
    declarations = '\n'.join(f'layout(location={i}) patch in vec4 p{i};' for i in indices)
    total = sum(i+1 for i in indices)
    expression = '+'.join(f'p{i}*{i+1}.0' for i in indices)
    SOURCES[f'PatchEval{name}'] = ('tese', '''#version 450
layout(triangles,equal_spacing,cw) in;
layout(location=0) out vec4 color;
''' + declarations + '''
void main() {
 gl_Position=gl_TessCoord.x*gl_in[0].gl_Position+gl_TessCoord.y*gl_in[1].gl_Position+gl_TessCoord.z*gl_in[2].gl_Position;
 color=(''' + expression + f')/{total}.0;\n}}\n')
header = '// SPDX-License-Identifier: GPL-2.0-or-later\n// Generated by generate.py; synthetic GLSL, no game data.\n#pragma once\n#include <cstdint>\n'
with tempfile.TemporaryDirectory() as tmp:
    for name, (stage, source) in SOURCES.items():
        path = Path(tmp)/f'{name}.{stage}'
        path.write_text(source)
        out = Path(tmp)/f'{name}.spv'
        subprocess.run(['glslangValidator','-V','--target-env','vulkan1.2',str(path),'-o',str(out)],check=True)
        words=struct.unpack('<'+'I'*(len(out.read_bytes())//4),out.read_bytes())
        header += f'\nstatic const uint32_t k{name}[] = {{\n'
        for i in range(0,len(words),8):
            header += '    '+', '.join(f'0x{v:08x}' for v in words[i:i+8])+',\n'
        header += '};\n'
(HERE/'shaders.h').write_text(header)
